            partition_id="COMMIT-PARTITION",
            current_candidate_event_record_id="UNRELATED-CANDIDATE",
            cutoff_utc=_T0 + timedelta(seconds=4),
            coordinator_clock=lambda: _T0 + timedelta(seconds=5),
